/* Canvas scene renderer for the recovered vector artwork. No SWF or bytecode. */
function sceneSnapshots(def){
 if(def.states)return def.states;
 let state={};def.states=def.frames.map((f,i)=>{for(const op of f.ops){if(op.remove){delete state[op.depth];continue;}const prev=state[op.depth];state[op.depth]={...(op.move?prev:{}),...op,key:(!prev||!op.move||op.id!==undefined&&op.id!==prev.id)?i+':'+op.depth:prev.key};}return {...state};});return def.states;
}
class SceneNode{
 constructor(player,id){this.player=player;this.id=id;this.def=player.data.defs[id]||{kind:'empty'};this.children=new Map();this.frame=-1;this.playing=true;this.wait=null;this.matrix=[1,0,0,1,0,0];this.color=[1,1,1,1,0,0,0,0];}
 seek(frame){if(this.def.kind!=='clip')return;this.apply(Math.max(0,Math.min(this.def.frames.length-1,frame)));this.run();}
 apply(frame){this.frame=frame;const state=sceneSnapshots(this.def)[frame];for(const [depth,node]of this.children)if(!state[depth]||state[depth].key!==node.key){this.children.delete(depth);}
  for(const [depth,op]of Object.entries(state)){let node=this.children.get(depth);if(!node){node=new SceneNode(this.player,op.id);node.key=op.key;this.children.set(depth,node);if(node.def.kind==='clip')node.seek(0);}node.matrix=op.m||[1,0,0,1,0,0];node.color=op.cx||[1,1,1,1,0,0,0,0];node.depth=Number(depth);node.clipDepth=op.clipDepth;}
 }
 run(){if(!this.player.actions)return;const frame=this.def.frames?.[this.frame];for(const action of frame?.scripts||[]){if(action.stop)this.playing=false;if(action.wait!==undefined){this.wait=action.wait*this.player.data.fps;this.playing=false;}if(action.goto!==undefined){this.playing=true;this.seek(action.goto);return;}}for(const id of frame?.sounds||[])this.player.onSound?.(id);}
 tick(){for(const child of this.children.values())child.tick();if(this.wait!==null){if(--this.wait<=0){this.wait=null;this.player.animate();}return;}if(this.playing&&this.def.frames?.length>1){this.apply((this.frame+1)%this.def.frames.length);this.run();}}
 find(id){if(this.id===id)return this;for(const c of this.children.values()){const found=c.find(id);if(found)return found;}return null;}
}
class VectorScenes{
 constructor(movies,resolve){this.movies=movies;this.resolve=resolve;this.images=new Map();this.tints=new Map();}
 async load(){await Promise.all(Object.values(this.movies).flatMap(m=>Object.values(m.defs)).filter(d=>d.url).map(d=>new Promise((ok,fail)=>{if(this.images.has(d.url)){ok();return;}const im=new Image();this.images.set(d.url,im);im.onload=ok;im.onerror=()=>fail(new Error('No se pudo cargar '+d.url));im.src=this.resolve(d.url);})));}
 image(ctx,def,tint){let im=this.images.get(def.url);if(!im?.naturalWidth)return;const key=def.url+':'+tint.join(',');if(tint.some((v,i)=>v!==(i<3?1:0))){let colored=this.tints.get(key);if(!colored){colored=document.createElement('canvas');colored.width=Math.ceil(im.naturalWidth*3);colored.height=Math.ceil(im.naturalHeight*3);const g=colored.getContext('2d');g.drawImage(im.image||im,0,0,colored.width,colored.height);const pixels=g.getImageData(0,0,colored.width,colored.height);for(let p=0;p<pixels.data.length;p+=4)for(let k=0;k<3;k++)pixels.data[p+k]=pixels.data[p+k]*tint[k]+tint[k+3];g.putImageData(pixels,0,0);this.tints.set(key,colored);}im=colored;}
  ctx.drawImage(im.image||im,...def.bounds);
 }
 draw(ctx,node,tint=[1,1,1,0,0,0]){
  ctx.save();ctx.transform(...node.matrix);const c=node.color||[1,1,1,1,0,0,0,0];ctx.globalAlpha*=Math.max(0,Math.min(1,c[3]+c[7]/255));const combined=[tint[0]*c[0],tint[1]*c[1],tint[2]*c[2],tint[3]+tint[0]*c[4],tint[4]+tint[1]*c[5],tint[5]+tint[2]*c[6]],d=node.def;
  if(d.kind==='image')this.image(ctx,d,combined);
  else if(d.kind==='button'){for(const op of d.up){const child=new SceneNode(node.player,op.id);child.matrix=op.m;child.color=op.cx;if(child.def.kind==='clip')child.seek(0);this.draw(ctx,child,combined);}}
  else if(d.kind==='clip'){
   const list=[...node.children.values()].sort((a,b)=>a.depth-b.depth);
   for(let i=0;i<list.length;i++){const mask=list[i];if(mask.clipDepth>mask.depth){const group=[];while(i+1<list.length&&list[i+1].depth<=mask.clipDepth)group.push(list[++i]);if(!group.length)continue;const buffer=document.createElement('canvas');buffer.width=ctx.canvas.width;buffer.height=ctx.canvas.height;const g=buffer.getContext('2d');g.setTransform(ctx.getTransform());for(const child of group)this.draw(g,child,combined);const stencil=document.createElement('canvas');stencil.width=buffer.width;stencil.height=buffer.height;const s=stencil.getContext('2d');s.setTransform(ctx.getTransform());this.draw(s,mask,combined);g.resetTransform();g.globalCompositeOperation='destination-in';g.drawImage(stencil,0,0);ctx.save();ctx.resetTransform();ctx.drawImage(buffer,0,0);ctx.restore();}else this.draw(ctx,mask,combined);}
  }
  ctx.restore();
 }
 symbol(ctx,movie,id,frame=0){const player={data:this.movies[movie],actions:false};const node=new SceneNode(player,id);if(node.def.kind==='clip')node.seek(frame);this.draw(ctx,node);}
 fitted(ctx,movie,id,x,y,w,h){const def=this.movies[movie].defs[id];if(!def?.bounds)return;const b=def.bounds;ctx.save();ctx.translate(x,y);ctx.scale(w/b[2],h/b[3]);ctx.translate(-b[0],-b[1]);this.symbol(ctx,movie,id);ctx.restore();}
}
class LogoAnimation{
 constructor(canvas,scenes,onSound){this.canvas=canvas;this.scenes=scenes;this.data=scenes.movies.logo;this.actions=true;this.onSound=onSound;this.resetPose();}
 resetPose(){this.root=new SceneNode(this,0);this.root.seek(1);}
 animate(){this.resetPose();const actor=this.root.find(this.data.controller);if(!actor)return;const labels=actor.def.labels,variants=['ani1','ani2','ani3'];const next=variants[Math.floor(Math.random()*variants.length)];actor.wait=null;actor.playing=true;actor.seek(labels[next]);}
 step(){let actor=this.root.find(this.data.controller);if(actor?.wait!==null){if(actor.frame!==0){this.resetPose();actor=this.root.find(this.data.controller);}if(--actor.wait<=0)this.animate();return;}this.root.tick();actor=this.root.find(this.data.controller);if(actor?.wait!==null&&actor.frame!==0)this.resetPose();}
 draw(){const ctx=this.canvas.getContext('2d');ctx.setTransform(this.canvas.width/this.data.width,0,0,this.canvas.height/this.data.height,0,0);ctx.clearRect(0,0,this.data.width,this.data.height);this.scenes.draw(ctx,this.root);}
}

/* Native rules recovered from the four archived header minigames. */
class MemoryGame{
 constructor(random=Math.random){this.random=random;this.phase='idle';this.sequence=[];this.flash=-1;this.time=0;this.input=0;this.tap=-1;this.tapTime=0;this.choices=[];}
 start(){this.sequence=[Math.floor(this.random()*4)];this.phase='show';this.time=0;this.flash=-1;this.input=0;this.tap=-1;this.tapTime=0;this.choices=[];}
 update(dt){this.tapTime=Math.max(0,this.tapTime-dt);if(!['show','input','between'].includes(this.phase))return;this.time+=dt;if(this.phase==='show'){const n=Math.floor((this.time-.35)/.55),part=(this.time-.35)% .55;this.flash=n>=0&&n<this.sequence.length&&part<.35?this.sequence[n]:-1;if(this.time>.35+this.sequence.length*.55){this.phase='input';this.time=0;this.flash=-1;}}
  else if(this.phase==='input'&&this.time>=12)this.phase='lost';
  else if(this.phase==='between'&&this.time>=.6){this.sequence.push(Math.floor(this.random()*4));this.input=0;this.choices=[];this.phase='show';this.time=0;}}
 choose(color){if(this.phase!=='input'||!Number.isInteger(color)||color<0||color>3)return false;this.tap=color;this.tapTime=.18;this.choices.push(color);this.input++;if(this.input===this.sequence.length){this.phase=this.choices.every((n,i)=>n===this.sequence[i])?(this.sequence.length===15?'won':'between'):'lost';this.time=0;}return true;}
}
const ticLines=[[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];
class TicGame{
 constructor(random=Math.random){this.random=random;this.phase='idle';this.twoPlayer=false;this.matches={won:0,lost:0,tie:0};this.round=0;}
 start(){this.twoPlayer=false;this.board=Array(9).fill(0);this.turn=1;this.phase='playing';this.strike=null;this.pending=0;this.round++;if(this.round%2===1){this.pending=.25;this.turn=2;}}
 check(){for(const line of ticLines)if(this.board[line[0]]&&line.every(i=>this.board[i]===this.board[line[0]])){this.strike=line;this.phase=this.board[line[0]]===1?'won':'lost';this.matches[this.phase]++;return;}if(this.board.every(Boolean)){this.phase='tie';this.matches.tie++;}}
 choose(i){if(this.phase!=='playing'||this.pending||i<0||i>8||this.board[i])return false;this.board[i]=this.turn;this.check();if(this.phase==='playing'){this.turn=3-this.turn;if(!this.twoPlayer)this.pending=.3;}return true;}
 computer(){const b=this.board;let candidate=-1;for(const x of [2,1]){for(const line of ticLines)if(line.filter(i=>b[i]===x).length===2){const empty=line.find(i=>!b[i]);if(empty!==undefined)candidate=empty;}if(!b[0]&&(b[4]===x||b[8]===x))candidate=0;}
  if(candidate<0){const empty=b.map((v,i)=>v?null:i).filter(i=>i!==null);candidate=empty[Math.floor(this.random()*empty.length)];}if(candidate===undefined)return;this.board[candidate]=2;this.check();this.turn=1;}
 update(dt){if(this.phase==='playing'&&this.pending>0){this.pending-=dt;if(this.pending<=0){this.pending=0;this.computer();}}}
}
class PaddleGame{
 constructor(random=Math.random){this.random=random;this.phase='idle';this.keys=new Set();this.bounds={left:4,right:60,top:19,bottom:63,radius:2.2,paddleHalf:6,paddleY:57,paddleHeight:2.5};}
 setPaddle(x){const b=this.bounds;this.paddle=Math.max(b.left+b.paddleHalf,Math.min(b.right-b.paddleHalf,x));}
 start(){this.phase='playing';this.x=32;this.y=28;this.vx=this.random()<.5?-1.5:1.5;this.vy=1.7;this.setPaddle(32);this.score=0;this.acc=0;this.trail=[];this.keys.clear();}
 update(dt){if(this.phase!=='playing')return;const b=this.bounds,left=b.left+b.radius,right=b.right-b.radius,top=b.top+b.radius,contact=b.paddleY-b.radius;this.acc+=dt;while(this.acc>=1/25&&this.phase==='playing'){this.acc-=1/25;this.setPaddle(this.paddle+(this.keys.has('ArrowRight')?5:0)-(this.keys.has('ArrowLeft')?5:0));this.trail.unshift({x:this.x,y:this.y});this.trail.length=Math.min(this.trail.length,16);const old=this.y;this.x+=this.vx;this.y+=this.vy;
 if(this.x<left){this.x=2*left-this.x;this.vx=Math.abs(this.vx);}else if(this.x>right){this.x=2*right-this.x;this.vx=-Math.abs(this.vx);}
 if(this.y<top){this.y=2*top-this.y;this.vy=2;}
 if(this.vy>0&&old<=contact&&this.y>=contact){const t=(contact-old)/this.vy,hitX=this.x-this.vx*(1-t);if(Math.abs(hitX-this.paddle)<=b.paddleHalf+b.radius){this.y=contact;const offset=Math.max(-1,Math.min(1,(hitX-this.paddle)/b.paddleHalf));this.vx=offset*2.6;if(Math.abs(this.vx)<1.15)this.vx=(this.vx<0?-1:this.vx>0?1:this.random()<.5?-1:1)*1.15;if(this.paddle<=b.left+b.paddleHalf+1)this.vx=Math.max(1.6,Math.abs(this.vx));else if(this.paddle>=b.right-b.paddleHalf-1)this.vx=-Math.max(1.6,Math.abs(this.vx));this.vy=-(4.6+this.score*.03);if(++this.score===15)this.phase='won';}}
 if(this.y>=b.bottom-b.radius){this.y=b.bottom-b.radius;this.phase='lost';}}}
}
class MinesGame{
 constructor(random=Math.random){this.random=random;this.phase='idle';this.mines=1;this.mark=false;this.uiTime=0;this.hoverStart=false;}
 start(){if(this.phase==='won')this.mines=Math.min(14,this.mines+1);this.phase='playing';this.mark=false;this.cells=Array.from({length:15},()=>({mine:false,open:false,flag:false,count:0}));const pool=Array.from({length:15},(_,i)=>i);for(let n=0;n<this.mines;n++){const i=Math.floor(this.random()*pool.length);this.cells[pool.splice(i,1)[0]].mine=true;}for(let i=0;i<15;i++)this.cells[i].count=this.neighbors(i).filter(n=>this.cells[n].mine).length;}
 neighbors(i){const result=[];for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){const x=i%5+dx,y=Math.floor(i/5)+dy;if((dx||dy)&&x>=0&&x<5&&y>=0&&y<3)result.push(y*5+x);}return result;}
 choose(i){if(this.phase!=='playing'||i<0||i>=15)return false;const c=this.cells[i];if(c.open)return false;if(c.flag){c.flag=false;return true;}if(this.mark){if(this.cells.filter(c=>c.flag).length>=this.mines)return false;c.flag=true;if(this.cells.filter(c=>c.mine).every(c=>c.flag))this.finish('won');return true;}if(c.mine){this.finish('lost');return true;}const queue=[i];while(queue.length){const n=queue.pop(),cell=this.cells[n];if(cell.open||cell.mine||cell.flag)continue;cell.open=true;if(!cell.count)queue.push(...this.neighbors(n).filter(k=>!this.cells[k].open));}return true;}
 finish(phase){this.phase=phase;for(const cell of this.cells)cell.open=true;}
 update(dt){this.uiTime+=dt;}
}

const TIC_BOARD={x:7,y:20,width:50,height:41};
class MiniGameView{
 constructor(canvas,art,live,onNote,index=0){this.canvas=canvas;this.art=art;this.live=live;this.onNote=onNote;this.index=index;this.select(index);canvas.addEventListener('pointerdown',e=>{canvas.focus();const p=this.point(e);this.press(p.x,p.y);if(this.model instanceof PaddleGame)canvas.setPointerCapture?.(e.pointerId);});canvas.addEventListener('pointerleave',()=>{if(this.model instanceof MinesGame||this.model instanceof MemoryGame){this.model.hoverStart=false;this.draw();}});canvas.addEventListener('pointermove',e=>{if(this.model instanceof MinesGame||this.model instanceof MemoryGame){const p=this.point(e);this.model.hoverStart=this.model instanceof MinesGame?p.x>=1&&p.x<=63&&p.y>=1&&p.y<=16:p.x>=3&&p.x<=63&&p.y>=29&&p.y<=50;this.draw();}if(this.model instanceof PaddleGame&&this.model.phase==='playing')this.model.setPaddle(this.point(e).x);});canvas.addEventListener('keydown',e=>this.key(e));canvas.addEventListener('keyup',e=>this.model.keys?.delete(e.key));canvas.addEventListener('blur',()=>this.model.keys?.clear());}
 select(i){this.index=i;this.model=new [MemoryGame,TicGame,PaddleGame,MinesGame][i]();this.name=['Memoria','Tres en línea','Pelota','Buscaminas'][i];this.previousPhase=null;this.draw();this.announce();}
 next(){this.select((this.index+1)%4);}
 point(e){const r=this.canvas.getBoundingClientRect();return {x:(e.clientX-r.left)*64/r.width,y:(e.clientY-r.top)*66/r.height};}
 press(x,y){const m=this.model;if(m.countdown>0)return;if(m instanceof MemoryGame&&['idle','won','lost'].includes(m.phase)&&!(x>=3&&x<=63&&y>=(m.phase==='idle'?29:18)&&y<=62))return;if(m instanceof MinesGame&&['idle','won','lost'].includes(m.phase)&&!(x>=1&&x<=63&&y>=1&&y<=16))return;if(['idle','won','lost','tie'].includes(m.phase)){m.countdown=3;this.onNote?.(-1);this.draw();this.announce();return;}
  if(m instanceof MemoryGame){if(x<5||x>60||y<20||y>63)return;const dx=x-33,dy=y-41;const n=Math.abs(dx)>Math.abs(dy)?dx>0?1:3:dy>0?2:0;if(m.choose(n))this.onNote?.(n);}
  else if(m instanceof TicGame){const b=TIC_BOARD;if(x>=b.x&&x<b.x+b.width&&y>=b.y&&y<b.y+b.height)m.choose(Math.floor((y-b.y)/(b.height/3))*3+Math.floor((x-b.x)/(b.width/3)));}
  else if(m instanceof MinesGame){if(x>=6&&x<=18&&y>=2&&y<=16)m.mark=!m.mark;else if(x>=7&&x<57&&y>=20&&y<50)m.choose(Math.floor((y-20)/10)*5+Math.floor((x-7)/10));}
  this.draw();this.announce();
 }
 key(e){if(!['Enter',' ','1','2','3','4','5','6','7','8','9','ArrowLeft','ArrowRight','f','F'].includes(e.key))return;e.preventDefault();const m=this.model;if(m.countdown>0)return;if(e.key==='Enter'||e.key===' '){if(['idle','won','lost','tie'].includes(m.phase))this.press(32,m instanceof MinesGame?9:30);return;}if(m instanceof PaddleGame)m.keys.add(e.key);else if(m instanceof MemoryGame&&Number(e.key)>=1&&Number(e.key)<=4){if(m.choose(Number(e.key)-1))this.onNote?.(Number(e.key)-1);}else if(m instanceof TicGame)m.choose(Number(e.key)-1);else if(m instanceof MinesGame&&e.key.toLowerCase()==='f')m.mark=!m.mark;this.draw();this.announce();}
 announce(){const m=this.model,phase=m.phase,state=m.countdown>0?'countdown-'+Math.ceil(m.countdown):phase;if(state===this.previousPhase)return;this.previousPhase=state;if(m.countdown>0){this.live.textContent=this.name+'. '+Math.ceil(m.countdown);this.canvas.setAttribute('aria-label',this.live.textContent);this.canvas.title=this.live.textContent;return;}const info={idle:'Haz clic para jugar.',show:'Observa la secuencia.',input:'Repite la secuencia de colores.',playing:this.index===2?'Mueve la paleta con el ratón o las flechas.':this.index===3?'Descubre casillas y marca las minas.':'Elige una casilla.',between:'Correcto.',won:'¡Ganaste! Haz clic para volver a jugar.',lost:'¡Perdiste! Haz clic para volver a jugar.',tie:'Empate. Haz clic para volver a jugar.'};this.live.textContent=this.name+'. '+info[phase];this.canvas.setAttribute('aria-label',this.live.textContent);this.canvas.title=this.live.textContent;}
 update(dt){const m=this.model;if(m.countdown>0){m.countdown=Math.max(0,m.countdown-dt);if(m.countdown<1e-8){m.countdown=0;m.start();}this.announce();return;}const old=m.flash;m.update(dt);if(m instanceof MemoryGame&&m.phase==='show'&&m.flash>=0&&m.flash!==old)this.onNote?.(m.flash);this.announce();}
 drawPaddle(ctx){const m=this.model,b=m.bounds;this.art.symbol(ctx,'game1',9);this.art.symbol(ctx,'game3',24);ctx.save();ctx.translate(6.15,0);this.art.symbol(ctx,'game3',19);ctx.restore();
 if(m.phase==='idle'&&!(m.countdown>0)){ctx.fillStyle='#1a2c73';ctx.fillRect(3,18,58,45);this.art.fitted(ctx,'game3',28,8,21,48,6);this.art.fitted(ctx,'game3',29,10,30,44,28);return;}
 if(['won','lost'].includes(m.phase)){ctx.fillStyle='#1a2c73';ctx.fillRect(3,18,58,45);if(m.phase==='lost'){this.art.fitted(ctx,'game1','perdiste',8,26,48,6.6);this.art.fitted(ctx,'game1',43,12,38,40,18);}else this.art.fitted(ctx,'game3',47,8,26,48,27);return;}
 ctx.fillStyle='#fff';ctx.fillRect(b.left,b.top,b.right-b.left,b.bottom-b.top);ctx.save();ctx.beginPath();ctx.rect(b.left,b.top,b.right-b.left,b.bottom-b.top);ctx.clip();
 const digits=String(m.score||0),dw=13,gap=1,total=digits.length*(dw+gap)-gap;for(let i=0;i<digits.length;i++)this.art.fitted(ctx,'game3','score'+digits[i],32-total/2+i*(dw+gap),35,dw,16);
 for(const [i,p]of (m.trail||[]).entries()){const fade=1-i/16;ctx.globalAlpha=fade*.85;ctx.fillStyle='#3333cc';ctx.beginPath();ctx.arc(p.x,p.y,Math.max(.45,b.radius*fade),0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;this.art.fitted(ctx,'game3',16,(m.x??32)-b.radius,(m.y??28)-b.radius,b.radius*2,b.radius*2);this.art.fitted(ctx,'game3',7,(m.paddle??32)-b.paddleHalf,b.paddleY,b.paddleHalf*2,b.paddleHeight);ctx.restore();
 if(m.countdown>0){ctx.fillStyle='#969bcf';ctx.fillRect(b.left,b.top,b.right-b.left,b.bottom-b.top);ctx.fillStyle='#fff';ctx.font='bold 24px Arial';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(String(Math.ceil(m.countdown)),32,40);}
 }
 drawMemory(ctx){const m=this.model;if(m.phase==='idle'&&!(m.countdown>0)){this.art.symbol(ctx,'game1',0,13);if(m.hoverStart){ctx.save();ctx.translate(31.15,39.5);ctx.scale(1,1.5659485);this.art.symbol(ctx,'game1',11);ctx.restore();ctx.save();ctx.translate(19.2,33.7);this.art.symbol(ctx,'game1',14);ctx.restore();}return;}this.art.symbol(ctx,'game1',9);this.art.symbol(ctx,'game1',6);ctx.save();ctx.translate(7.7,1.75);this.art.symbol(ctx,'game1',17);ctx.restore();this.art.symbol(ctx,'game1',21);ctx.save();ctx.translate(33.8,85.1);const flash=m.tapTime>0?m.tap:m.flash;this.art.symbol(ctx,'game1',27,flash>=0?[9,29,69,49][flash]:0);ctx.restore();
 if(m.countdown>0){ctx.fillStyle='#1a2c73dd';ctx.fillRect(4.4,18.85,55.4,42.85);ctx.fillStyle='#fff';ctx.font='bold 24px Arial';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(String(Math.ceil(m.countdown)),32,40);return;}
 if(['lost','won'].includes(m.phase)&&m.tapTime<=0){ctx.fillStyle='#969bcfe0';ctx.fillRect(4.4,18.85,55.4,42.85);ctx.strokeStyle='#d5dcff80';ctx.lineWidth=.5;ctx.strokeRect(5.5,20,53.2,40.5);if(m.phase==='lost'){this.art.fitted(ctx,'game1','perdiste',11,24,42,5.8);this.art.fitted(ctx,'game1',43,12,35,40,18);}else this.art.fitted(ctx,'game1',57,8,29,48,20);}
 }
 drawMines(ctx){const m=this.model,ended=['won','lost'].includes(m.phase),playing=m.phase==='playing';this.art.symbol(ctx,'game4',32);ctx.fillStyle='#003366';ctx.fillRect(2,52,60,12);ctx.textAlign='left';ctx.textBaseline='middle';ctx.fillStyle='#fff';ctx.font='bold 7px Arial';ctx.fillText('MINAS',9,58);if(m.cells){ctx.font='bold 9px Arial';ctx.fillText(String(m.mines-m.cells.filter(c=>c.flag).length),43,58);}
 if(!playing){ctx.fillStyle=m.hoverStart&&!(m.countdown>0)?'#c5caef':'#003366';ctx.fillRect(2,2,60,13);ctx.fillStyle=m.hoverStart&&!(m.countdown>0)?'#003366':'#fff';ctx.font='bold 8px Arial';ctx.textAlign='center';ctx.fillText('JUGAR',32,8.5);}else{this.art.fitted(ctx,'game4',17,7,3,10,10);if(m.mark){ctx.fillStyle='#0005';ctx.fillRect(8,4,8,8);}ctx.fillStyle='#fff';ctx.font='bold 6.7px Arial';ctx.textAlign='left';ctx.fillText('< MARCAR',20,8.5);}
 if(m.cells)for(let i=0;i<15;i++){const c=m.cells[i],x=7+i%5*10,y=20+Math.floor(i/5)*10;ctx.save();ctx.translate(x,y);this.art.symbol(ctx,'game4',12,ended?c.mine?1:2:c.flag?3:c.open?2:0);ctx.restore();if(c.open&&!c.mine&&c.count){ctx.fillStyle='#fff';ctx.font='bold 6.5px Arial';ctx.textAlign='center';ctx.fillText(String(c.count),x+5,y+4.5);}}
 if(m.countdown>0){ctx.fillStyle='#969bcf';ctx.fillRect(4,18,56,32);ctx.fillStyle='#fff';ctx.font='bold 24px Arial';ctx.textAlign='center';ctx.fillText(String(Math.ceil(m.countdown)),32,34);return;}
 if(m.phase==='idle')this.art.fitted(ctx,'game4',Math.floor(m.uiTime/.4)%2?30:29,12,29,40,8);
 if(ended){ctx.fillStyle='#a4b4e7';ctx.fillRect(3,28,58,14);this.art.fitted(ctx,'game4',m.phase==='won'?35:37,7,31,50,8);}
 }
 draw(){const ctx=this.canvas.getContext('2d');ctx.setTransform(this.canvas.width/64,0,0,this.canvas.height/66,0,0);ctx.fillStyle='#969bcf';ctx.fillRect(0,0,64,66);ctx.strokeStyle='#0900e2';ctx.lineWidth=2;ctx.strokeRect(1,1,62,64);if(this.model instanceof MinesGame){this.drawMines(ctx);return;}if(this.model instanceof MemoryGame){this.drawMemory(ctx);return;}if(this.model instanceof PaddleGame){this.drawPaddle(ctx);return;}this.art.fitted(ctx,'game1',17,5,4,54,7);
  const m=this.model;ctx.font='bold 4.6px Arial, sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillStyle='#172e70';ctx.fillText(this.name.toUpperCase()+(m instanceof MemoryGame&&m.sequence.length?' '+m.sequence.length+'/15':''),32,15);
  if(m.countdown>0){ctx.fillStyle='#1a2c73';ctx.fillRect(3,20,58,44);ctx.fillStyle='#fff';ctx.font='bold 24px Arial, sans-serif';ctx.fillText(String(Math.ceil(m.countdown)),32,41);return;}
  if(['won','lost','tie'].includes(m.phase)&&!(m instanceof MemoryGame&&m.tapTime>0)){ctx.fillStyle='#1a2c73';ctx.fillRect(3,20,58,44);if(m.phase==='lost'){this.art.fitted(ctx,'game1','perdiste',4,25,56,8);this.art.fitted(ctx,'game1',43,11,37,42,17);}else if(m.phase==='won')this.art.fitted(ctx,'game1',57,6,27,52,18);else{ctx.fillStyle='white';ctx.font='bold 7px Arial';ctx.fillText('EMPATE',32,34);ctx.font='bold 5px Arial';ctx.fillText('vuelve a jugar',32,47);}return;}
  if(m instanceof MemoryGame){this.art.symbol(ctx,'game1',21);ctx.save();ctx.translate(33.8,85.1);const flash=m.tapTime>0?m.tap:m.flash;this.art.symbol(ctx,'game1',27,flash>=0?[9,29,69,49][flash]:0);ctx.restore();}
  else if(m instanceof TicGame){const b=TIC_BOARD,cw=b.width/3,ch=b.height/3;ctx.fillStyle='#171ad6';ctx.fillRect(b.x,b.y,b.width,b.height);ctx.strokeStyle='#eeeefe';ctx.lineWidth=.6;for(let i=1;i<3;i++){ctx.beginPath();ctx.moveTo(b.x+i*cw,b.y+1);ctx.lineTo(b.x+i*cw,b.y+b.height-1);ctx.stroke();ctx.beginPath();ctx.moveTo(b.x+1,b.y+i*ch);ctx.lineTo(b.x+b.width-1,b.y+i*ch);ctx.stroke();}for(let i=0;i<9;i++){const v=m.board?.[i]||0,x=b.x+(i%3+.5)*cw,y=b.y+(Math.floor(i/3)+.5)*ch;if(!v)continue;ctx.strokeStyle=v===1?'#ffffff':'#9eefff';ctx.lineWidth=1.4;ctx.beginPath();if(v===1){ctx.moveTo(x-3.8,y-3.8);ctx.lineTo(x+3.8,y+3.8);ctx.moveTo(x+3.8,y-3.8);ctx.lineTo(x-3.8,y+3.8);}else ctx.arc(x,y,4.4,0,Math.PI*2);ctx.stroke();}}

  if(m.phase==='idle'){ctx.fillStyle='#1a2d72d9';ctx.fillRect(10,38,44,11);ctx.fillStyle='#fff';ctx.font='bold 7px Arial';ctx.fillText('¡JUEGA!',32,43.8);}
 }
}

const templateCSS=`
:host{display:block;width:100%;max-width:1060px;color:#101830;font-family:Calibri,Arial,sans-serif}*{box-sizing:border-box}a{color:inherit}button{font:inherit;cursor:pointer}button:focus-visible,a:focus-visible,canvas:focus-visible{outline:2px solid #fff58a;outline-offset:-2px}.viewport{width:100%;position:relative;overflow:hidden}.stage{width:1060px;height:238px;display:grid;grid-template-columns:298px 762px;grid-template-rows:91px 36px 53px 20px 38px;transform-origin:top left;background:#818ddf}.logo-block{grid-column:1;grid-row:1/5;display:flex;height:200px;width:299px;position:relative;z-index:1;background:#193075}.logo-link{display:block;width:242px;height:200px;position:relative;background:#d0d6ee}.logo-link canvas,.logo-link img{position:absolute;inset:0;width:242px;height:200px}.logo-link canvas{opacity:0}.logo-link.ready canvas{opacity:1}.logo-link.ready img{opacity:0}.divider{width:58px;height:200px;margin-left:-1px;flex:none;background:#193075}.sound{position:absolute;left:8px;top:177px;z-index:2;border:1px solid #7d8ac0;background:#c4d1f1cc;color:#203e82;width:23px;height:18px;padding:0;font:11px Arial}.media{grid-column:2;grid-row:1;display:flex;align-items:flex-start;padding:4px 0 0 3px}.ad-link{display:flex;width:660px;height:83px;background:#000;overflow:hidden}.ad-label{width:20px;flex:none;display:flex;justify-content:center;align-items:center}.ad-label img{width:11px;height:60px}.ad{width:640px;height:83px;object-fit:fill}.mini{position:relative;display:flex;justify-content:center;width:99px;height:83px;background:#9297cb}.mini canvas{width:80.5px;height:83px;display:block;touch-action:none;cursor:pointer}.mini-control{position:absolute;right:0;width:13px;height:14px;padding:0;border:0;color:#edf1ff;background:#1d2e7bcf;line-height:13px;font:11px Arial}.switch{top:0}.expand{bottom:0}.schedule{grid-column:2;grid-row:2;display:grid;grid-template-columns:160px 275px 275px 52px;height:36px}.schedule a,.schedule img{display:block}.schedule img{height:36px}.slot{position:relative;background:#afc1ec}.slot.next{background:#9fb5ea}.slot .eyebrow{position:absolute;left:60px;top:0;font-size:12px;line-height:14px}.slot time{position:absolute;left:5px;top:18px;font-size:15px;line-height:17px}.slot .program{right:6px;overflow:hidden;text-overflow:ellipsis;position:absolute;left:60px;top:18px;font-size:15px;line-height:17px;font-weight:400;white-space:nowrap}.characters{position:relative;grid-column:2;grid-row:3;display:grid;grid-template-columns:54px minmax(0,1fr) 54px;background:#808be0;height:53px}.characters button{border:0;padding:0;background:transparent;height:53px}.prev,.next-button{background-size:54px 53px;background-repeat:no-repeat!important}.prev{transform:scaleX(-1)}.previous-disabled{opacity:.65}.character-window{overflow:hidden;height:53px}.track{display:flex;width:200%;height:53px;transition:transform .22s ease-out}.page{width:50%;height:53px;position:relative;background-size:100% 100%;background-repeat:no-repeat;padding:0;margin:0;list-style:none;flex:none}.page li{position:absolute;top:0;height:53px}.page a{display:block;width:100%;height:100%;text-decoration:none}.page a{position:relative}.page li:hover,.page li:focus-within{z-index:2}.character-animation{position:absolute;left:0;right:0;top:9px;height:34px;pointer-events:none;background-repeat:no-repeat}.character-animation[hidden]{display:none}.character-blue{display:none;position:absolute;left:0;right:0;top:9px;height:34px;pointer-events:none;overflow:hidden}.character-blue::before,.character-blue::after{content:"";position:absolute;inset:0;background:#0877cc;clip-path:polygon(0 0,100% 0,55% 100%,0 70%);transform:translateX(-110%)}.character-blue::after{background:#193075;clip-path:polygon(40% 0,100% 25%,100% 100%,0 100%)}.character-fallback .character-blue{display:block}.character-fallback.is-active .character-blue::before{animation:character-wipe .5s ease-out both}.character-fallback.is-active .character-blue::after{animation:character-wipe .5s .06s ease-out both}@keyframes character-wipe{0%{transform:translateX(-110%)}45%{transform:translateX(0)}100%{transform:translateX(110%)}}@media(prefers-reduced-motion:reduce){.character-blue{display:none!important}}.spacer{grid-column:2;grid-row:4;background:#193075}.bottom-cap{grid-column:1;grid-row:5;width:299px;position:relative;z-index:1;background-color:#b5c9ee;background-size:299px 38px}.navigation{grid-column:2;grid-row:5;display:flex;gap:12px;padding:5px 0 0 10px;background:#b5c9ee;height:38px}.navigation a,.navigation img{display:block;width:149px;height:27px}.navigation a:hover{filter:brightness(1.12)}.sr-only{position:absolute!important;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}.expanded{border:2px solid #7d8be0;background:#193075;color:#eef2ff;padding:12px;max-width:calc(100vw - 20px)}.expanded::backdrop{background:#071633b8}.expanded .large-canvas{display:block;width:min(256px,75vw);height:auto;aspect-ratio:64/66;touch-action:none;image-rendering:auto}.dialog-controls{display:flex;justify-content:space-between;gap:8px;margin-top:10px}.dialog-controls button{background:#b5c9ee;color:#193075;border:1px solid #818ddf;padding:6px 10px;font-size:13px}@media(prefers-reduced-motion:reduce){.track{transition:none}}
`;
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
class JetixHeader extends HTMLElement{
 constructor(){super();this.attachShadow({mode:'open'});this.page=0;this.adIndex=0;this.soundEnabled=true;this.audioUnlocked=false;this.audios=new Set();this.isHovered=false;this.motionReduced=matchMedia('(prefers-reduced-motion: reduce)').matches;this.disposed=false;this.lifecycle=0;}
 asset(url){return DATA.inlineAssets?.[url]||DATA.inlineAds?.[url]||DATA.inlineVectors?.[url]||new URL(url,SCRIPT_BASE).href;}
 connectedCallback(){if(this.started)return;this.started=true;this.disposed=false;this.page=0;this.adIndex=0;const generation=++this.lifecycle;const a=p=>escapeHTML(this.asset(p));const schedule=this.getSchedule();
  const pages=DATA.characters.map((page,index)=>`<ul class="page" aria-label="Personajes ${index+1}" ${index?'inert aria-hidden="true"':''} style="background-image:url('${a(page.image)}')">${page.links.map((c,characterIndex)=>`<li style="left:${c.left/654*100}%;width:${c.width/654*100}%"><a data-character="${index}-${characterIndex}" href="${escapeHTML(c.href)}" title="${escapeHTML(c.name)}" aria-label="${escapeHTML(c.name)}"><span class="character-animation" aria-hidden="true" hidden></span><span class="character-blue" aria-hidden="true"></span></a></li>`).join('')}</ul>`).join('');
  this.shadowRoot.innerHTML=`<style>${templateCSS}</style><div class="viewport"><header class="stage" aria-label="Encabezado de Jetix Latin America"><div class="logo-block"><a class="logo-link" href="${escapeHTML(DATA.home)}" aria-label="Jetix Latin America, inicio"><img src="${a(DATA.poster)}" alt="Jetix"><canvas width="484" height="400" aria-hidden="true"></canvas></a><img class="divider" src="${a(DATA.divider)}" alt="" aria-hidden="true"></div><button class="sound" type="button" aria-label="${this.soundEnabled?'Silenciar encabezado':'Activar sonido del encabezado'}" title="${this.soundEnabled?'Silenciar':'Activar sonido'}">${this.soundEnabled?'♪':'♪×'}</button><div class="media"><a class="ad-link" href="${escapeHTML(DATA.adHref)}"><span class="ad-label"><img src="${a(DATA.adLabel)}" alt="Publicidad"></span><img class="ad" src="${a(DATA.adPlayback[0].poster)}" alt="${escapeHTML(DATA.adNames[0])}"></a><div class="mini"><canvas class="mini-canvas" width="256" height="264" tabindex="0" aria-label="Minijuego de Jetix"></canvas><button class="mini-control switch" aria-label="Cambiar minijuego" title="Cambiar minijuego">↻</button><button class="mini-control expand" aria-label="Ampliar minijuego" title="Ampliar minijuego">⤢</button></div></div><nav class="schedule" aria-label="Programación"><a href="${escapeHTML(DATA.scheduleHref)}"><img src="${a(DATA.scheduleImage)}" width="160" alt="Programación"></a><div class="slot current"><span class="eyebrow">estás viendo</span><time>${escapeHTML(schedule.now.time)}</time><span class="program">${escapeHTML(schedule.now.name)}</span></div><div class="slot next"><span class="eyebrow">ya viene</span><time>${escapeHTML(schedule.next.time)}</time><span class="program">${escapeHTML(schedule.next.name)}</span></div><a href="${escapeHTML(DATA.scheduleHref)}"><img src="${a(DATA.moreImage)}" width="52" alt="Más programación"></a></nav><nav class="characters" aria-label="Personajes de Jetix"><button class="prev" type="button" aria-label="Personajes anteriores" style="background-image:url('${a(DATA.arrow)}')"></button><div class="character-window"><div class="track">${pages}</div></div><button class="next-button" type="button" aria-label="Siguientes personajes" style="background-image:url('${a(DATA.arrow)}')"></button></nav><div class="spacer"></div><div class="bottom-cap" style="background-image:url('${a(DATA.bottom)}')"></div><nav class="navigation" aria-label="Secciones">${DATA.navigation.map(n=>`<a href="${escapeHTML(n.href)}"><img src="${a(n.image)}" alt="${escapeHTML(n.name)}"></a>`).join('')}</nav></header></div><div class="sr-only status" aria-live="polite"></div><div class="sr-only slider-status" aria-live="polite"></div><dialog class="expanded" aria-label="Minijuego Jetix ampliado"><canvas class="large-canvas" width="512" height="528" tabindex="0"></canvas><div class="dialog-controls"><button class="dialog-next">Cambiar Juego</button><button class="dialog-close">Cerrar</button></div><span class="sr-only dialog-status" aria-live="polite"></span></dialog>`;
  const q=s=>this.shadowRoot.querySelector(s);this.q=q;
  this.resizeObserver=new ResizeObserver(()=>this.resize());this.resizeObserver.observe(this);this.resize();
  this.setupArrows();this.setupCharacters();
  this.scheduleMinute=null;this.updateSchedule();
  q('.prev').onclick=()=>this.changePage(-1,true);q('.next-button').onclick=()=>this.changePage(1,true);q('.characters').onkeydown=e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();this.changePage(e.key==='ArrowLeft'?-1:1,true);}};q('.characters').onpointerenter=()=>this.isHovered=true;q('.characters').onpointerleave=()=>this.isHovered=false;
  this.audioGesture=e=>this.unlockAudio(e);for(const type of ['pointerdown','pointerup','click','keydown'])document.addEventListener?.(type,this.audioGesture,true);this.shadowRoot.addEventListener('pointerdown',this.audioGesture);this.shadowRoot.addEventListener('keydown',this.audioGesture);
  q('.sound').onclick=()=>{this.audioUnlocked=true;this.pendingLogoSound=null;this.soundEnabled=!this.soundEnabled;q('.sound').textContent=this.soundEnabled?'♪':'♪×';q('.sound').setAttribute('aria-label',this.soundEnabled?'Silenciar encabezado':'Activar sonido del encabezado');q('.sound').title=this.soundEnabled?'Silenciar':'Activar sonido';if(this.soundEnabled)this.playSound('logo',1);else for(const audio of this.audios){audio.pause();this.audios.delete(audio);}};
  q('.logo-link').onpointerenter=()=>{this.logo?.animate();this.manualLogo=true;};q('.logo-link').onfocus=()=>{this.logo?.animate();this.manualLogo=true;};
  this.art=new VectorScenes(DATA.movies,p=>this.asset(p));
  this.ready=this.art.load().then(()=>{if(this.disposed||generation!==this.lifecycle)return;this.logo=new LogoAnimation(q('.logo-link canvas'),this.art,id=>this.playSound('logo',id));this.logo.draw();this.playSound('logo',1,true);q('.logo-link').classList.add('ready');const initial=Number.isInteger(DATA.initialGame)?DATA.initialGame:Math.floor(Math.random()*4);this.mini=new MiniGameView(q('.mini-canvas'),this.art,q('.status'),n=>{if(n>=0)this.playSound('game1',[4,3,2,1][n]);},initial);
   q('.switch').onclick=()=>this.changeGame();q('.expand').onclick=()=>this.expandGame();q('.dialog-next').onclick=()=>this.changeGame();q('.dialog-close').onclick=()=>q('.expanded').close();this.frame=0;this.slideTime=0;this.showAd(0);this.adVisibility=()=>{if(!document.hidden&&!this.disposed)this.showAd(this.adIndex);};document.addEventListener?.('visibilitychange',this.adVisibility);let last=performance.now(),acc=0;
   const loop=now=>{if(this.disposed||generation!==this.lifecycle)return;const elapsed=Math.max(0,(now-last)/1000),dt=Math.min(.1,elapsed);last=now;if(!document.hidden){this.updateSchedule();this.updateArrows(dt);this.updateCharacters(dt);acc+=dt;while(acc>=1/30){if(!this.motionReduced||this.manualLogo)this.logo.step();if(this.motionReduced&&this.logo.root.find(48)?.wait!==null)this.manualLogo=false;acc-=1/30;}this.mini.update(dt);this.mini.draw();this.logo.draw();if(q('.expanded').open&&this.large){this.large.draw();this.large.announce();}if(!this.motionReduced&&!this.isHovered&&!this.shadowRoot.activeElement){this.slideTime+=dt;if(this.slideTime>=5)this.changePage(1);}this.updateAds(elapsed);}this.raf=requestAnimationFrame(loop);};this.raf=requestAnimationFrame(loop);this.dataset.ready='true';this.dispatchEvent(new CustomEvent('jetix-ready'));}).catch(e=>{q('.status').textContent=e.message;console.error(e);this.dataset.error=e.message;});
 }
 resize(){const width=Math.min(1060,this.getBoundingClientRect().width||1060),scale=width/1060;this.q('.stage').style.transform=`scale(${scale})`;this.q('.viewport').style.height=(238*scale)+'px';}
 getSchedule(date=new Date()){const entries=DATA.schedule.daily.entries,minute=date.getHours()*60+date.getMinutes();let index=entries.length-1;for(let i=0;i<entries.length;i++){if(entries[i].minute>minute)break;index=i;}return {minute,now:entries[index],next:entries[(index+1)%entries.length]};}
 updateSchedule(date=new Date()){const schedule=this.getSchedule(date);if(schedule.minute===this.scheduleMinute)return;this.scheduleMinute=schedule.minute;this.scheduleCurrent=schedule;for(const [selector,item]of [['.slot.current',schedule.now],['.slot.next',schedule.next]]){const time=this.q(selector+' time'),name=this.q(selector+' .program');time.textContent=item.time;time.setAttribute('datetime',item.time);name.textContent=item.name;name.title=item.name;const measure=this.scheduleMeasure||(this.scheduleMeasure=document.createElement('canvas').getContext('2d'));measure.font='15px Calibri, Arial, sans-serif';const width=name.clientWidth||209;name.style.fontSize=Math.max(10,Math.min(15,15*width/Math.max(1,measure.measureText(item.name).width)))+'px';}}
 setupCharacters(){this.characterStates=[];for(const [pageIndex,page]of DATA.characters.entries())for(const [index,link]of page.links.entries()){const selector=`[data-character="${pageIndex}-${index}"]`,el=this.q(selector),overlay=this.q(selector+' .character-animation'),state={el,overlay,def:link.animation,active:false,hover:false,focus:false,time:0,frame:0};this.characterStates.push(state);if(state.def){overlay.style.backgroundImage=`url('${this.asset(state.def.sheet)}')`;overlay.style.backgroundSize=`${state.def.count*100}% 100%`;const v=state.def.viewport;overlay.style.left=v.left+'%';overlay.style.right='auto';overlay.style.width=v.width+'%';overlay.style.top=v.top+'px';overlay.style.height=v.height+'px';}else el.classList.add('character-fallback');const sync=()=>this.activateCharacter(state,state.hover||state.focus);el.onpointerenter=()=>{state.hover=true;sync();};el.onpointerleave=()=>{state.hover=false;sync();};el.onpointercancel=()=>{state.hover=false;sync();};el.onpointerdown=()=>{state.pointerFocus=true;state.focus=false;sync();};el.onfocus=()=>{state.focus=!state.pointerFocus&&el.matches(':focus-visible');sync();};el.onkeydown=()=>{state.pointerFocus=false;state.focus=true;sync();};el.onblur=()=>{state.pointerFocus=false;state.focus=false;sync();};}}
 activateCharacter(s,active){if(s.active===active)return;s.active=active;s.time=0;s.looped=false;s.frame=1;s.el.classList[active?'add':'remove']('is-active');s.overlay.hidden=!active||!s.def;if(s.def)this.drawCharacter(s);}
 drawCharacter(s){const visualFrame=s.looped?Math.max(s.def.loopVisualStart,s.frame):s.frame;s.overlay.style.backgroundPosition=`${visualFrame/(s.def.count-1)*100}% 0px`;}
 updateCharacters(dt){for(const s of this.characterStates||[]){if(!s.active||!s.def)continue;s.time+=dt;while(s.time>=1/s.def.fps){s.time-=1/s.def.fps;s.frame++;if(s.frame>=s.def.count){s.frame=s.def.loop;s.looped=true;}}this.drawCharacter(s);}}
 resetCharacters(){for(const s of this.characterStates||[]){s.hover=false;s.focus=false;s.pointerFocus=false;this.activateCharacter(s,false);}}
 setupArrows(){this.arrowStates={};for(const [side,selector]of [['left','.prev'],['right','.next-button']]){const def=DATA.arrowAnimations.right,el=this.q(selector),state={def,el,frame:0,end:0,time:0,playing:false,hover:false,focus:false};this.arrowStates[side]=state;el.style.backgroundImage=`url('${this.asset(def.sheet)}')`;el.style.backgroundSize=`${def.width*def.count}px 53px`;this.drawArrow(state);const sync=()=>this.animateArrow(side,state.hover||state.focus);el.onpointerenter=()=>{state.hover=true;sync();};el.onpointerleave=()=>{state.hover=false;sync();};el.onpointercancel=()=>{state.hover=false;sync();};el.onpointerdown=()=>{state.pointerFocus=true;state.focus=false;sync();};el.onkeydown=()=>{state.pointerFocus=false;state.focus=true;sync();};el.onfocus=()=>{state.focus=!state.pointerFocus&&el.matches(':focus-visible');sync();};el.onblur=()=>{state.pointerFocus=false;state.focus=false;sync();};}}
 drawArrow(state){state.el.style.backgroundPosition=`-${state.frame*state.def.width}px 0px`;}
 animateArrow(side,active){const s=this.arrowStates?.[side];if(!s||s.active===active)return;s.active=active;[s.frame,s.end]=s.def[active?'over':'out'];s.time=0;s.playing=!this.motionReduced;if(this.motionReduced)s.frame=active?s.end:0;this.drawArrow(s);}
 updateArrows(dt){for(const s of Object.values(this.arrowStates||{})){if(!s.playing)continue;s.time+=dt;while(s.time>=1/30&&s.playing){s.time-=1/30;if(s.frame<s.end)s.frame++;else{s.playing=false;if(!s.active)s.frame=0;}}this.drawArrow(s);}}
 changePage(dir,userInitiated=false){this.resetCharacters();if(userInitiated){this.audioUnlocked=true;this.playSound('carousel',234);}this.page=(this.page+dir+2)%2;this.slideTime=0;this.q('.track').style.transform=`translateX(-${this.page*50}%)`;for(const [i,p]of [...this.shadowRoot.querySelectorAll('.page')].entries()){p.inert=i!==this.page;p.setAttribute('aria-hidden',String(i!==this.page));}this.q('.slider-status').textContent='Personajes: página '+(this.page+1)+' de 2';}
 showAd(index){this.adIndex=index;this.adTime=0;this.adLoaded=false;const img=this.q('.ad');img.onload=()=>{if(!this.disposed){this.adLoaded=true;this.adTime=0;}};if(this.adObjectURL){URL.revokeObjectURL(this.adObjectURL);this.adObjectURL=null;}let url=this.asset(DATA.ads[index]);if(url.startsWith('data:')&&typeof URL.createObjectURL==='function'&&typeof Blob==='function'&&typeof atob==='function'){const comma=url.indexOf(','),mime=url.slice(5,url.indexOf(';')),binary=atob(url.slice(comma+1)),bytes=Uint8Array.from(binary,c=>c.charCodeAt(0));this.adObjectURL=URL.createObjectURL(new Blob([bytes],{type:mime}));url=this.adObjectURL;}img.alt=DATA.adNames[index];img.src=url;}
 updateAds(dt){if(!this.adLoaded)return;this.adTime+=dt;if(this.adTime+1e-8>=DATA.adPlayback[this.adIndex].duration)this.changeAd();}
 changeAd(){this.showAd((this.adIndex+1)%DATA.ads.length);}
 changeGame(){this.mini?.next();if(this.large){this.large.index=this.mini.index;this.large.name=this.mini.name;this.large.model=this.mini.model;this.large.previousPhase=null;this.large.announce();this.large.draw();}}
 expandGame(){if(!this.mini)return;if(!this.large)this.large=new MiniGameView(this.q('.large-canvas'),this.art,this.q('.dialog-status'),n=>{if(n>=0)this.playSound('game1',[4,3,2,1][n]);},this.mini.index);this.large.index=this.mini.index;this.large.name=this.mini.name;this.large.model=this.mini.model;this.large.previousPhase=null;this.large.draw();this.large.announce();this.q('.expanded').showModal();this.q('.large-canvas').focus();}
 unlockAudio(event){this.audioUnlocked=true;if(event?.composedPath?.().includes(this.q('.sound')))return;if(this.pendingLogoSound&&this.soundEnabled){const id=this.pendingLogoSound;this.pendingLogoSound=null;this.playSound('logo',id);}}
 playSound(movie,id,initial=false){if(!this.soundEnabled||(!this.audioUnlocked&&!initial))return;const url=DATA.movies[movie].sounds[id];if(!url)return;if(movie==='logo'){if([...this.audios].filter(a=>a.jetixChannel==='logo').length>=8)return;}else for(const audio of [...this.audios]){if(audio.jetixChannel===movie){audio.pause();this.audios.delete(audio);}}const audio=new Audio(this.asset(url));audio.jetixChannel=movie;audio.volume=.35;this.audios.add(audio);audio.onended=()=>this.audios.delete(audio);return audio.play().then(()=>{if(this.disposed||!this.audios.has(audio))return;this.audioUnlocked=true;if(movie==='logo')this.pendingLogoSound=null;}).catch(error=>{const active=this.audios.delete(audio);if(active&&!this.disposed&&this.soundEnabled&&movie==='logo'&&error?.name==='NotAllowedError'){this.pendingLogoSound=1;this.audioUnlocked=false;}});}
 disconnectedCallback(){this.disposed=true;this.started=false;this.lifecycle++;for(const type of ['pointerdown','pointerup','click','keydown'])document.removeEventListener?.(type,this.audioGesture,true);this.shadowRoot.removeEventListener?.('pointerdown',this.audioGesture);this.shadowRoot.removeEventListener?.('keydown',this.audioGesture);this.pendingLogoSound=null;cancelAnimationFrame(this.raf);document.removeEventListener?.('visibilitychange',this.adVisibility);if(this.adObjectURL){URL.revokeObjectURL(this.adObjectURL);this.adObjectURL=null;}this.adLoaded=false;this.resizeObserver?.disconnect();for(const audio of this.audios)audio.pause();this.audios.clear();}
}
window.JetixHeaderInternals={MemoryGame,TicGame,PaddleGame,MinesGame,SceneNode,VectorScenes,LogoAnimation,MiniGameView,DATA};
if(!customElements.get('jetix-header'))customElements.define('jetix-header',JetixHeader);

